#![no_std]
use core::hint::black_box;
#[no_mangle]
pub extern "C" fn f(a: u8, b: u8) -> u8 {
let a = black_box(a ^ 108u8);
let a = a ^ 108u8;
let b = black_box(b ^ 13u8);
let b = b ^ 13u8;
let z = a.wrapping_add(b);
let z = black_box(z ^ 111u8);
let z = z ^ 111u8;
z
}

